package cn.zaozhi;

import cn.zaozhi.agent.*;
import cn.zaozhi.tool.*;
import cn.zaozhi.brief.BriefValidator;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class V11RuntimeTest {
    @TempDir Path dir;
    ToolContext context(Map<String,String> options)throws Exception {var config=new HashMap<>(options);config.put("DATA_DIR",dir.toString());var settings=new Settings(config);var db=new Database(settings);var p=Profile.validate(Json.object("nickname","runtime","email","private@example.com","exclude",List.of("BLOCKED")));var user=db.createUser(p);String rid=db.claim(user.path("id").asText(),p,settings.mode(),"manual",null);return new ToolContext(rid,user.path("id").asText(),p,db,settings);}
    com.fasterxml.jackson.databind.node.ObjectNode empty(){return Json.object("title","Brief","intro","No eligible new items","items",List.of());}
    @Test void failedCandidateUpdateKeepsLastAcceptedAndAllFailedSourcesCannotPublishEmpty()throws Exception {var ctx=context(Map.of());var tools=new ToolRegistry(new NewsClient());assertEquals("NO_USABLE_SOURCE",tools.execute("publish_brief",empty(),ctx).path("error_code").asText());ctx.remember(Json.arr());assertTrue(tools.execute("publish_brief",empty(),ctx).path("ok").asBoolean());var old=ctx.candidate;assertFalse(tools.execute("publish_brief",Json.object("title","invalid"),ctx).path("ok").asBoolean());assertSame(old,ctx.candidate);}
    @Test void readonlyContextAndRealShellDoNotExposeEmailOrHostPaths()throws Exception {var ctx=context(Map.of());var tools=new ToolRegistry(new NewsClient());assertFalse(Json.stringify(tools.execute("read_file",Json.object("path","context.json"),ctx)).contains("private@example.com"));for(String path:List.of("preferences.json","sources.json","articles/x.txt","../x","notes/../x","C:/x","//host/share"))assertFalse(tools.execute("write_file",Json.object("path",path,"content","x"),ctx).path("ok").asBoolean(),path);assertEquals("/workspace",tools.execute("bash",Json.object("command","pwd"),ctx).path("data").path("stdout").asText().strip());assertTrue(tools.execute("write_file",Json.object("path","notes/ok.txt","content","abcdef"),ctx).path("ok").asBoolean());assertEquals("cd",tools.execute("read_file",Json.object("path","notes/ok.txt","offset",2,"max_chars",2),ctx).path("data").asText());assertFalse(tools.execute("read_file",Json.object("path","notes/ok.txt","max_chars",8001),ctx).path("ok").asBoolean());}
    @Test void entireOverBudgetBatchIsRejectedBeforeAnySideEffect()throws Exception {var ctx=context(Map.of("MAX_TOOL_CALLS","1"));var request=DemoClient.call("write_file",Json.object("path","notes/a","content","first"));((com.fasterxml.jackson.databind.node.ArrayNode)request.path("tool_calls")).add(DemoClient.call("write_file",Json.object("path","notes/b","content","second")).path("tool_calls").get(0));var failure=assertThrows(AgentFailure.class,()->new AgentRunner((m,t,d)->request,new ToolRegistry(new NewsClient())).run(ctx));assertEquals("BUDGET_EXCEEDED",failure.code);assertFalse(Files.exists(dir.resolve("workspaces").resolve(ctx.runId).resolve("notes/a")));}
    @Test void fixedWindowRejectsFutureAndExclusionCoversTitleIntroAndReadBody()throws Exception {var ctx=context(Map.of());var source=(com.fasterxml.jackson.databind.node.ObjectNode)NewsClient.demoNews().get(0);source.put("published_at",ctx.windowEnd.toString());ctx.remember(Json.arr().add(source));var candidate=Json.object("title","Brief","intro","Intro","items",List.of(Json.object("source_id","demo-agent","summary","Summary","why_it_matters","Why")));var validator=new BriefValidator();assertEquals(1,validator.validate(candidate,ctx).path("items").size());((com.fasterxml.jackson.databind.node.ObjectNode)ctx.sources.get("demo-agent")).put("published_at",ctx.windowEnd.plusSeconds(1).toString());assertThrows(IllegalArgumentException.class,()->validator.validate(candidate,ctx));((com.fasterxml.jackson.databind.node.ObjectNode)ctx.sources.get("demo-agent")).put("published_at",ctx.windowEnd.toString());candidate.put("intro","BLOCKED");assertThrows(IllegalArgumentException.class,()->validator.validate(candidate,ctx));candidate.put("intro","Intro");ctx.bodies.put("demo-agent","BLOCKED in extracted body");assertThrows(IllegalArgumentException.class,()->validator.validate(candidate,ctx));}
    @Test void articleIsReadonlySearchableAndCarriesEvidenceScope()throws Exception {var ctx=context(Map.of());var tools=new ToolRegistry(new NewsClient());tools.execute("search_news",Json.object("query","AI"),ctx);var article=tools.execute("fetch_article",Json.object("source_id","demo-agent"),ctx);assertEquals("articles/demo-agent.txt",article.path("data").path("path").asText());assertTrue(tools.execute("search_content",Json.object("keyword","Agent","dir","articles"),ctx).path("data").size()>0);assertEquals("AVAILABLE",ctx.db.one("SELECT body_state FROM run_sources WHERE run_id=? AND source_id='demo-agent'",ctx.runId).path("body_state").asText());}
    @Test void livePlaceholderCannotBeRecordedAsExtractedBody()throws Exception {var ctx=context(Map.of("DEMO_MODE","false"));var source=(com.fasterxml.jackson.databind.node.ObjectNode)NewsClient.demoNews().get(0);source.put("published_at",ctx.windowEnd.toString());ctx.remember(Json.arr().add(source));var tools=new ToolRegistry(new NewsClient(){@Override public String article(String url,ToolContext c){return "Google News";}});assertFalse(tools.execute("fetch_article",Json.object("source_id","demo-agent"),ctx).path("ok").asBoolean());assertFalse(ctx.bodies.containsKey("demo-agent"));assertNotEquals("AVAILABLE",ctx.db.one("SELECT body_state FROM run_sources WHERE run_id=? AND source_id='demo-agent'",ctx.runId).path("body_state").asText());var candidate=Json.object("title","Brief","intro","RSS evidence only","items",List.of(Json.object("source_id","demo-agent","summary","RSS summary","why_it_matters","Why")));assertEquals("rss_excerpt",new BriefValidator().validate(candidate,ctx).path("items").get(0).path("evidence_scope").asText());}
    @Test void sourcePreviewOmitsLongLinksWhileFullReadonlyIndexRetainsAllSources()throws Exception {var ctx=context(Map.of("DEMO_MODE","false"));var rows=Json.arr();for(int i=0;i<12;i++)rows.add(Json.object("source_id","s"+i,"title","AI title "+i,"url","https://news.google.com/rss/articles/"+"x".repeat(1200)+i,"source","publisher","published_at",ctx.windowEnd.toString(),"excerpt","内容".repeat(1000)));var tools=new ToolRegistry(new NewsClient(){@Override public com.fasterxml.jackson.databind.node.ArrayNode feed(String url,ToolContext c){return rows;}});var result=tools.execute("search_news",Json.object("query","AI"),ctx);assertTrue(result.path("ok").asBoolean());assertEquals(5,result.path("data").path("sources").size());assertEquals(12,result.path("data").path("total_results").asInt());assertFalse(result.path("data").path("sources").get(0).has("url"));assertEquals(12,ctx.sources.size());assertTrue(Files.readString(dir.resolve("workspaces").resolve(ctx.runId).resolve("sources.json")).contains("x".repeat(1200)));assertTrue(Json.stringify(result).getBytes(java.nio.charset.StandardCharsets.UTF_8).length<6000);}
    @Test void workspaceQuotaAndUnknownTokenUsageRemainReserved()throws Exception {Workspace w=new Workspace(dir.resolve("small"),16);w.write("notes/a","1234567890");assertThrows(IllegalArgumentException.class,()->w.write("notes/b","1234567890"));var ctx=context(Map.of("RUN_TOKEN_LIMIT","5000"));int reserved=ctx.budget.reserve("fixture");ctx.budget.usage(reserved,Json.obj());assertEquals(reserved,ctx.db.one("SELECT reserved_tokens FROM runs WHERE id=?",ctx.runId).path("reserved_tokens").asInt());assertThrows(AgentFailure.class,()->ctx.budget.reserve("second"));}
    @Test void contextLimitFailsBeforeModelRequest()throws Exception {var ctx=context(Map.of("CONTEXT_TOKEN_LIMIT","100"));int[] attempts={0};assertThrows(AgentFailure.class,()->new AgentRunner((m,t,d)->{attempts[0]++;return Json.object("role","assistant","content","done");},new ToolRegistry(new NewsClient())).run(ctx));assertEquals(0,attempts[0]);}
    @Test void contradictoryFinishSignalIsRejectedByProviderAdapter()throws Exception {HttpServer server=HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat/completions",e->{byte[] b=Json.stringify(Json.object("choices",List.of(Json.object("finish_reason","tool_calls","message",Json.object("role","assistant","content","done"))))).getBytes();e.sendResponseHeaders(200,b.length);e.getResponseBody().write(b);e.close();});server.start();try{var settings=new Settings(Map.of("DEMO_MODE","false","DEEPSEEK_API_KEY","fixture","LLM_BASE_URL","http://127.0.0.1:"+server.getAddress().getPort()));assertThrows(AgentFailure.class,()->new DeepSeekClient(settings).next(Json.arr(),Json.arr(),System.nanoTime()+TimeUnit.SECONDS.toNanos(3)));}finally{server.stop(0);}}
    @Test void traceExternalObjectsAreRedactedAndForeignSubscriptionCannotReadThem()throws Exception {var ctx=context(Map.of());ctx.db.event(ctx.runId,"tool",Json.object("name","fixture","result",Json.object("ok",true,"data","x".repeat(5000)+" private@example.com")));var row=ctx.db.one("SELECT * FROM events WHERE run_id=?",ctx.runId);assertEquals("EXTERNAL",row.path("payload_state").asText());assertFalse(Json.stringify(ctx.db.events(ctx.userId,ctx.runId)).contains("private@example.com"));assertThrows(cn.zaozhi.controller.ApiException.class,()->ctx.db.events("other",ctx.runId));Files.delete(dir.resolve("artifacts").resolve(row.path("payload_ref").asText()));assertEquals("MISSING",ctx.db.events(ctx.userId,ctx.runId).get(0).path("payload_state").asText());}
}
